BEGIN ATOMIC
 IF (SELECT count(*) FROM client_dev.ashlar_edge_ingest_20261005_l1.stage s JOIN client_dev.ashlar_edge_ingest_20261005_l1.edge_current e ON s.source_system=e.source_system AND s.rel_type_id=e.rel_type_id AND s.id=e.id WHERE e.id<=200000 AND (e.props_json IS DISTINCT FROM s.props_json OR e.entity_version<>s.entity_version))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='edge prior mismatch'; END IF;
 MERGE INTO client_dev.ashlar_edge_ingest_20261005_l1.edge_current e USING client_dev.ashlar_edge_ingest_20261005_l1.stage s ON e.source_system=s.source_system AND e.rel_type_id=s.rel_type_id AND e.id=s.id AND e.id<=200000 WHEN MATCHED THEN UPDATE SET e.props_json=s.new_props,e.entity_version=1,e.source_position=1,e.published_at=current_timestamp();
 INSERT INTO client_dev.ashlar_edge_ingest_20261005_l1.property_journal SELECT source_system,'edge',rel_type_id,id,201,1,'update',true,substring(to_json(array(get_json_object(props_json,'$.201'))),2,length(to_json(array(get_json_object(props_json,'$.201'))))-2),true,substring(to_json(array(get_json_object(new_props,'$.201'))),2,length(to_json(array(get_json_object(new_props,'$.201'))))-2),schema_revision,source_feed,source_epoch,1,id,'synthetic-edge-batch:1',current_timestamp() FROM client_dev.ashlar_edge_ingest_20261005_l1.stage;
 IF (SELECT count(*) FROM client_dev.ashlar_edge_ingest_20261005_l1.stage s JOIN client_dev.ashlar_edge_ingest_20261005_l1.edge_current e ON s.source_system=e.source_system AND s.rel_type_id=e.rel_type_id AND s.id=e.id WHERE e.id<=200000)<>200000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='edge cardinality'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_edge_ingest_20261005_l1.stage s JOIN client_dev.ashlar_edge_ingest_20261005_l1.edge_current e ON s.id=e.id WHERE e.id<=200000 AND (e.props_json IS DISTINCT FROM s.new_props OR e.retained_json IS DISTINCT FROM s.retained_json OR e.source_type<>s.source_type OR e.source_id<>s.source_id OR e.target_type<>s.target_type OR e.target_id<>s.target_id OR e.entity_version<>1))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='edge carrier/endpoints'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_edge_ingest_20261005_l1.property_journal)<>200000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='edge journal count'; END IF;
 IF (SELECT count(*) FROM client_dev.ashlar_edge_ingest_20261005_l1.property_journal j JOIN client_dev.ashlar_edge_ingest_20261005_l1.stage s ON j.id=s.id WHERE from_json(concat('[',j.old_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.props_json,'$.201') OR from_json(concat('[',j.new_json,']'),'ARRAY<STRING>')[0] IS DISTINCT FROM get_json_object(s.new_props,'$.201'))<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='edge journal values'; END IF;
 INSERT INTO client_dev.ashlar_edge_ingest_20261005_l1.receipt VALUES (1,current_timestamp()); END
